const r=[{id:"v1",parentId:null,kind:"volume",title:"卷一 · 风起青萍",order:0,status:"completed"},{id:"c1",parentId:"v1",kind:"chapter",title:"渡口初见",order:0,status:"completed",wordCount:3210},{id:"c2",parentId:"v1",kind:"chapter",title:"雨夜同行",order:1,status:"draft",wordCount:1876},{id:"v2",parentId:null,kind:"volume",title:"卷二 · 山雨欲来",order:1,status:"draft"},{id:"c3",parentId:"v2",kind:"chapter",title:"旧地重游",order:0,status:"draft",wordCount:542}],d=[{id:"e1",kind:"character",title:"沈青梧",summary:"青渡口摆渡人，左耳后有一道旧疤；话不多，记性极好。",tags:["主角","摆渡"],revision:"r3"},{id:"e2",kind:"location",title:"青渡口",summary:"淮河支流的小码头，黄昏起雾，只留一盏渔灯。",tags:["场景"],revision:"r1"},{id:"e3",kind:"organization",title:"旧漕帮",summary:"早年跑船的行会，如今散作几路人马，暗中仍有联络。",tags:["势力"],revision:"r2"},{id:"e4",kind:"item",title:"铜铃",summary:"沈青梧随身的铜铃，铃声只在起风前响。",tags:["伏笔"],revision:"r1"},{id:"e5",kind:"note",title:"写作备忘",summary:"",tags:["笔记"],revision:"r1"}],a={c1:"渡口的雾还没散，沈青梧把缆绳绕上木桩，回头看见那个穿灰布衫的旅人正站在石阶尽头，肩上行李滴水未沾。",c2:"雨是后半夜落下来的。两人挤在渡船的小篷底下，听雨声打在竹篷上，谁也没有先开口。",c3:"三年后再回青渡口，渔灯换了新的，唯有那棵老槐树还站在原处，枝桠斜斜探向水面。"};function n(t){const e=r.find(i=>i.id===t);return!e||e.kind!=="chapter"?null:{chapterId:t,baseRevision:"r1",changeId:"init",text:a[t],format:"plain-text"}}export{d as a,n as b,r as d};
